'use strict';
const $ = (s, root=document) => root.querySelector(s);
const $$ = (s, root=document) => [...root.querySelectorAll(s)];
const esc = v => String(v ?? '').replace(/[&<>"']/g, c => ({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const pretty = v => v === null || v === undefined ? '—' : typeof v === 'object' ? JSON.stringify(v) : String(v);
const label = v => String(v || 'unknown').replaceAll('_',' ');
const pill = (value, text) => `<span class="pill ${esc(value)}">${esc(text || label(value))}</span>`;
const source = (file, fn, text='View implementation ↗') => `<button class="text-button" data-source="${esc(file)}" data-function="${esc(fn || '')}">${esc(text)}</button>`;
const names = {classroom:'Live classroom',evidence:'Evidence ledger',review:'Review lab',architecture:'How it works',trace:'Engine trace'};
const state = {mode:'demo',view:'classroom',snapshot:null,token:'',busy:false,polling:false,selectedNode:null,selectedCard:null,selectedEvent:null,traceTab:'output',showNotes:false,draft:'',draftPending:null,met:new Set(),metPending:null,signature:'',errorCount:0};
const phases = [
  {id:'prepare',title:'Prepare',owner:'Claude + preparation commands',file:'teach',fn:'',text:'Claude prepares objectives, explanations, misconceptions, checks and answer keys. prep-topic and prep-node persist this material. The demo loads prepared fixtures; it does not invoke research or a model.'},
  {id:'teach',title:'Teach',owner:'Claude, guided by the teaching skill',file:'teach',fn:'',text:'In a normal session Claude motivates and explains one prepared concept. This dashboard can observe saved preparation and progress, but cannot see unsaved teaching or claim that Claude is currently thinking.'},
  {id:'question',title:'Ask',owner:'state.py · cmd_ask()',file:'state',fn:'cmd_ask',text:'ask saves the exact pending question, selected variant, rubric version and assistance history before waiting for an answer. A restart can recover this interaction.'},
  {id:'assessment',title:'Assess',owner:'Claude or an explicit presenter assessment',file:'state',fn:'cmd_answer',text:'answer saves the learner response and changes the pending stage to recorded. Claude normally judges it against the prepared rubric. Here, assessments are explicitly supplied by the presenter or guided-demo script, not by AI.'},
  {id:'evidence',title:'Record',owner:'state.py + srs.py + learnlib.Store',file:'state',fn:'cmd_record',text:'record takes a structured assessment, updates evidence, applies assistance and grade rules, creates or grades a review card, and commits state plus deck through the original store.'},
  {id:'review',title:'Review',owner:'srs.py · apply_grade()',file:'scheduler',fn:'apply_grade',text:'Review cards have real due dates, intervals and history. Independent dated success can extend an interval; help caps the quality, practice success does not extend it, and failure schedules the card for tomorrow.'},
  {id:'resume',title:'Resume',owner:'hook_session_start.py',file:'hook',fn:'main',text:'The SessionStart hook reconstructs context from saved state. The demo executes that actual hook in a fresh process. It does not restart Claude or expose hidden model reasoning.'}
];

async function api(path, options={}) {
  const response = await fetch(path, {cache:'no-store',...options});
  const data = await response.json();
  if (!response.ok) throw new Error(data.error || `Request failed (${response.status})`);
  return data;
}
function toast(message,error=false){const el=$('#toast');el.textContent=message;el.className=`toast show${error?' error':''}`;clearTimeout(toast.timer);toast.timer=setTimeout(()=>el.classList.remove('show'),error?8500:4500);}
function modal(title,html,eyebrow='INSPECT THE SYSTEM'){$('#modal-title').textContent=title;$('#modal-eyebrow').textContent=eyebrow;$('#modal-body').innerHTML=html;if(!$('#modal').open)$('#modal').showModal();}
function setConnection(ok){const el=$('#connection');el.className=`connection${ok?'':' offline'}`;el.innerHTML=`<i></i>${ok?'Connected · 1.5s refresh':'Connection / state issue'}`;}
function changeView(view){if(!names[view])return;state.view=view;render();window.scrollTo({top:0,behavior:'instant'});}
async function load(force=false){
  if(state.busy||state.polling)return;
  state.polling=true;
  const requestedMode=state.mode;
  try{
    const s=await api(`/api/snapshot?mode=${requestedMode}`);
    if(requestedMode!==state.mode)return;
    const sig=JSON.stringify([s.mode,s.rev,s.deck_rev,s.date,s.tour?.tour_index,s.tour?.tour_custom,s.tour?.last_beat,s.events.at(-1)?.id,s.prep,s.warnings]);
    state.snapshot=s;state.errorCount=0;setConnection(true);
    if(force||sig!==state.signature){state.signature=sig;render();}
  }catch(error){setConnection(false);state.errorCount++;
    if(force||state.errorCount===1)toast(error.message,true);
    if(!state.snapshot)$('#content').innerHTML=`<div class="card empty"><h2>The dashboard could not read the engine state</h2><p>${esc(error.message)}</p><p class="m-top">Keep the Python server running, then use Refresh. Existing project files have not been overwritten.</p></div>`;
  }finally{state.polling=false;}
}
async function act(action,extra={}){
  if(state.busy)return;
  if(state.mode==='live'&&state.snapshot?.can_write){
    if(!confirm('This writes to your REAL project through its Python commands. Continue?'))return;
  }
  if(action==='reset'&&!confirm('Reset only the isolated demo? Your actual learner records will not be changed.'))return;
  state.busy=true;$('#busy-overlay').hidden=false;
  $('#busy-label').textContent=action==='reset'?'Preparing a fresh isolated lesson. Your real records are untouched.':action==='tour-next'?'Executing this demonstration step and reading the committed result.':'The view updates after the command commits.';
  try{
    const s=await api('/api/action',{method:'POST',headers:{'Content-Type':'application/json','X-Dashboard-Token':state.token},body:JSON.stringify({mode:state.mode,action,expected_rev:state.snapshot?.rev,...extra})});
    state.snapshot=s;state.signature='';
    if(action==='tour-next'){
      const beat=s.tour.steps[s.tour.last_beat];
      state.selectedNode=beat?.node || state.selectedNode;
      state.selectedEvent=null;
      if(beat?.stage==='review'){
        state.selectedCard=s.cards.find(c=>c.node===beat.node)?.id || null;
      }
    }
    if(action==='reset'){state.selectedNode=null;state.selectedCard=null;state.selectedEvent=null;state.draft='';state.met=new Set();}
    if(action==='answer')state.draft='';
    render();setConnection(true);
    if(action!=='tour-next'&&action!=='reset')toast('Engine command completed. Saved state has been refreshed.');
  }catch(error){toast(error.message,true);}
  finally{state.busy=false;$('#busy-overlay').hidden=true;await load();}
}
function currentBeat(){const t=state.snapshot?.tour;return t && t.last_beat!==null && !t.tour_custom ? t.steps[t.last_beat] : null;}
function currentPhase(){const phase=currentBeat()?.stage||state.snapshot?.stage;return phase==='repair'?'evidence':phase==='complete'?'review':phase==='paused'?'resume':phase==='idle'?'prepare':phase;}
function heading(title,subtitle){const s=state.snapshot;return `<div class="page-heading"><div><div class="eyebrow">LEARNING FOR LUNCH / ${state.mode==='demo'?'PRESENTATION WORKSPACE':'CONNECTED PROJECT'}</div><h1>${title}</h1><p>${subtitle}</p></div><div class="date-chip">${state.mode==='demo'?'DEMO CLOCK':'PROJECT DATE'} &nbsp; <strong>${esc(s.date)}</strong></div></div>`;}
function notice(){const s=state.snapshot;let html=state.mode==='demo'?`<div class="notice"><span>⊙</span><div><b>Isolated demo, real engine.</b> Prepared sample answers and assessments run through your unmodified Python scripts. No model is called; your actual records are untouched.</div></div>`:`<div class="notice ${s.can_write?'red':'warn'}"><span>${s.can_write?'!':'◉'}</span><div><b>${s.can_write?'Live writes enabled.':'Read-only live project.'}</b> ${s.can_write?'Browser actions can change real learning records. Coordinate with Claude before grading.':'Continue teaching in Claude Code; this view refreshes saved milestones every 1.5 seconds.'} It does not display unsaved activity or model thoughts.</div></div>`;if(s.warnings?.length)html+=`<div class="notice warn"><span>!</span><div>${s.warnings.map(esc).join('<br>')}</div></div>`;return html;}
function tour(){const t=state.snapshot.tour;if(!t)return '';const b=currentBeat();const done=t.tour_index>=t.steps.length;const title=t.tour_custom?'Explore the engine yourself':b?.title||'Follow one learner. See every decision.';const text=t.tour_custom?'Manual controls have changed this lesson. The state is real; the guided sequence is paused. Reset the isolated demo to replay the prepared story.':b?.text||'Move through a prepared lesson, introduce a misconception, record a hint, recover a question, and watch the review schedule adapt. Each step executes the project’s actual commands.';
 return `<section class="tour-card"><div class="tour-copy"><div class="eyebrow">${t.tour_custom?'EXPLORATION MODE':'GUIDED DEMONSTRATION · PREPARED INPUTS / REAL OUTPUTS'}</div><h2>${esc(title)}</h2><p>${esc(text)}</p><div class="tour-dots">${t.steps.map((_,i)=>`<i class="${i===t.last_beat?'current':i<t.tour_index?'done':''}" title="Step ${i+1}"></i>`).join('')}<span>${t.tour_index} / ${t.steps.length} steps</span></div></div><div class="tour-controls"><button class="primary" data-action="tour-next" ${done||t.tour_custom?'disabled':''}>${done?'Walkthrough complete':t.tour_index===0?'Begin walkthrough':'Next step'} <span>→</span></button><button class="text-button" data-ui="notes">${state.showNotes?'Hide':'Show'} speaker notes</button><button class="text-button" data-action="reset">↺ Reset isolated demo</button></div></section>${state.showNotes?`<div class="speaker-note"><b>PRESENTER NOTE</b>${esc(b?.say||'This is an adaptive tutor with persistent learning evidence. Claude handles teaching and assessment; Python enforces progress, evidence and review rules. The demo uses prepared inputs, so it works without a model connection.')}</div>`:''}`;
}
function phaseStrip(){const active=currentPhase();return `<div class="phase-strip" aria-label="Learning cycle">${phases.map((p,i)=>`${i?'<span class="arrow">→</span>':''}<button class="phase-button ${p.id===active?'active':''}" data-phase="${p.id}" title="${esc(p.owner)}"><b>${i+1}</b>${p.title}</button>`).join('')}</div>`;}
function metrics(){const s=state.snapshot,n=s.topic?.plan?.nodes||[];const count=(k,v)=>n.filter(x=>x[k]===v).length;const covered=count('coverage','covered'),ready=count('readiness','ready'),provisional=count('readiness','provisional'),retained=count('retention','demonstrated');const values=[['Coverage','▤',covered,'Concepts encountered',`${n.length-covered} not yet covered`],['Readiness','↗',ready,'Ready to build on',`${provisional} provisional · ${count('readiness','needs_repair')} need repair`],['Retention','↻',retained,'Positive review evidence',`${count('retention','needs_review')} need review`]];return `<div class="metrics">${values.map(([name,icon,value,a,b])=>`<section class="metric"><div class="metric-top"><span>${name}</span><span>${icon}</span></div><div class="metric-value">${value}<em>/ ${n.length}</em></div><div class="metric-bottom"><span>${a}</span><span>${b}</span></div><div class="mini-track"><i style="width:${n.length?value/n.length*100:0}%"></i></div></section>`).join('')}</div>`;}
function selectedNode(){const s=state.snapshot,nodes=s.topic?.plan?.nodes||[];let n=nodes.find(n=>n.id===state.selectedNode);if(!n)n=nodes.find(n=>n.id===s.pending?.node&&s.pending.stage!=='completed')||nodes.find(n=>n.id===s.eligibility.recommended)||nodes[0];state.selectedNode=n?.id||null;return n;}
function graph(){const s=state.snapshot,nodes=s.topic?.plan?.nodes||[];if(!nodes.length)return `<div class="empty">No lesson plan has been saved yet.</div>`;
 const depth={};function rank(n,seen=new Set()){if(depth[n.id]!==undefined)return depth[n.id];if(seen.has(n.id))return 0;seen.add(n.id);return depth[n.id]=n.depends?.length?1+Math.max(...n.depends.map(id=>{let d=nodes.find(x=>x.id===id);return d?rank(d,new Set(seen)):0})):0;}
 nodes.forEach(n=>rank(n));const layers=Math.max(...Object.values(depth))+1,maxRows=Math.max(...Array.from({length:layers},(_,d)=>nodes.filter(n=>depth[n.id]===d).length));const W=Math.max(800,layers*255+30),H=Math.max(282,maxRows*129+40);const positions={};
 for(let d=0;d<layers;d++){const ns=nodes.filter(n=>depth[n.id]===d);ns.forEach((n,i)=>positions[n.id]={x:28+d*(W-56-214)/Math.max(1,layers-1),y:H/2-(ns.length*126-22)/2+i*126});}
 const blocked=new Set(s.eligibility.blocked.map(b=>b.id)),repairs=new Set(s.eligibility.repairs);let edges='';nodes.forEach(n=>(n.depends||[]).forEach(id=>{const a=positions[id],b=positions[n.id];if(!a||!b)return;const x=a.x+214,y=a.y+46,tx=b.x,ty=b.y+46;edges+=`<path class="graph-edge ${repairs.has(id)?'repair':blocked.has(n.id)?'blocked':''}" d="M${x} ${y} C${x+30} ${y},${tx-30} ${ty},${tx} ${ty}" marker-end="url(#arrowhead)"/>`;}));
 let shapes=nodes.map(n=>{const p=positions[n.id],isBlocked=blocked.has(n.id);const cls=n.readiness==='needs_repair'?'repair':n.readiness==='provisional'?'provisional':n.readiness==='ready'?'ready':isBlocked?'blocked':'';const status=n.readiness==='needs_repair'?'Needs repair':n.coverage==='covered'?label(n.readiness):isBlocked?'Prerequisite not met':'Eligible to teach';let title=n.label.length>25?n.label.slice(0,23)+'…':n.label;return `<g class="graph-node ${cls} ${state.selectedNode===n.id?'selected':''}" transform="translate(${p.x},${p.y})" data-node="${esc(n.id)}" role="button" tabindex="0" aria-label="${esc(n.label)}: ${esc(status)}"><title>${esc(n.label)} — ${esc(status)}</title><rect class="node-box" width="214" height="93" rx="10"/><text class="node-id" x="15" y="22">${esc(n.id.toUpperCase())}</text><text class="node-label" x="15" y="47">${esc(title)}</text><text class="node-status" x="15" y="71">${n.readiness==='ready'?'✓ ':n.readiness==='needs_repair'?'! ':isBlocked?'○ ':'↗ '}${esc(status)}</text><circle cx="197" cy="20" r="3" fill="${cls==='repair'?'#c88174':cls==='ready'?'#74a482':cls==='provisional'?'#a590c8':'#ced8d0'}"/></g>`;}).join('');
 return `<div class="graph-wrap"><svg viewBox="0 0 ${W} ${H}" role="group" aria-label="Live prerequisite graph"><defs><marker id="arrowhead" viewBox="0 0 8 8" refX="7" refY="4" markerWidth="5" markerHeight="5" orient="auto"><path d="M0 0L8 4L0 8" fill="none" stroke="#a2b5a8"/></marker></defs>${edges}${shapes}</svg></div><div class="graph-legend"><span><i class="green"></i>Ready</span><span><i class="purple"></i>Provisional</span><span><i class="red"></i>Needs repair</span><span><i></i>Pending / blocked</span><span>Click a concept to inspect it</span></div>`;
}
function nodeDetail(){const s=state.snapshot,n=selectedNode();if(!n)return '';const p=s.prep[n.id],block=s.eligibility.blocked.find(b=>b.id===n.id),open=s.pending&&s.pending.stage!=='completed';const disabled=!s.can_write||!s.active_topic||open||block||!p;return `<div class="selection-detail"><div class="selection-title"><h3>${esc(n.label)}</h3>${pill(n.readiness)}</div><p>${esc(p?.objective||n.why||'No prepared objective saved for this concept.')}</p>${block?`<div class="hint-box">Blocked: ${block.reasons.map(esc).join('; ')}.</div>`:''}${n.readiness_note?`<p class="subtle">Evidence: ${esc(n.readiness_note)}</p>`:''}<div class="definition-grid">${['coverage','readiness','retention'].map(k=>`<div>${k.toUpperCase()}<br>${pill(n[k])}</div>`).join('')}</div><div class="selection-actions"><button class="text-button" data-ui="prep" data-node-id="${esc(n.id)}">Inspect prepared material ↗</button><button class="secondary small" data-ui="ask-node" data-node-id="${esc(n.id)}" ${disabled?'disabled':''}>${n.readiness==='needs_repair'?'Ask repair check':'Ask check'} →</button></div></div>`;}
function gradingPanel(p){if(state.metPending!==p.id){state.met=new Set();state.metPending=p.id;}const required=p.key?.required||[];return `<div class="border-top m-top"><div class="field-label">PRESENTER ASSESSMENT · NOT AUTOMATIC GRADING</div><p class="subtle">Tick the required points actually demonstrated. The engine, not this page, applies readiness and quality caps.</p><div class="checklist">${required.map((r,i)=>`<label><input type="checkbox" data-required="${i}" ${state.met.has(r)?'checked':''}><span>${esc(r)}</span></label>`).join('')}</div><div class="button-row"><select id="grade-quality" class="inline-select" aria-label="Requested quality"><option value="4">Quality 4 · correct</option><option value="5">Quality 5 · precise</option><option value="3">Quality 3 · laboured pass</option><option value="2">Quality 2 · incomplete</option><option value="1">Quality 1 · wrong</option><option value="0">Quality 0 · unknown</option></select><button class="primary small" data-ui="grade" data-result="pass">Record pass</button><button class="secondary small" data-ui="grade" data-result="fail">Record fail</button></div></div>`;}
function questionCard(){if(currentBeat()?.stage==='review')return reviewFocusCard();const s=state.snapshot,p=s.pending,open=p&&p.stage!=='completed';let body='';
 if(open){if(state.draftPending!==p.id){state.draftPending=p.id;state.draft='';}body=`<div class="pending-type">${pill('purple',p.type==='short'?'Short-answer check':label(p.type))}${pill(p.stage==='awaiting'?'amber':'green',p.stage==='awaiting'?'Awaiting answer':'Answer saved')}${pill('neutral',p.kind)}</div><div class="question">${esc(p.question)}</div>${p.assistance?.length?`<div class="hint-box"><b>Help recorded: ${p.assistance.map(esc).join(' → ')}</b><br>${esc(p.hints?.[Math.min(p.assistance.length-1,(p.hints?.length||1)-1)]||'A hint was given in the lesson.')}</div>`:''}`;
  if(p.response)body+=`<div class="field-label">SAVED LEARNER ANSWER</div><div class="recorded-answer">${esc(p.response)}</div>`;
  if(s.can_write&&p.stage==='awaiting')body+=`<textarea class="answer-box" id="learner-answer" placeholder="Enter a learner answer, or continue the guided demo…" maxlength="2000" aria-label="Learner answer">${esc(state.draft)}</textarea><div class="answer-actions"><button class="secondary small" data-action="hint">Give a recorded hint</button><button class="primary small" data-ui="save-answer">Save answer →</button></div>`;
  if(s.can_write&&p.stage==='recorded')body+=gradingPanel(p);
  if(!s.can_write)body+=`<p class="subtle m-top">Respond in Claude Code. This view observes saved state; it does not grade on its own.</p>`;
  body+=`<div class="m-top">${source('state','cmd_pending','How the question survives a restart ↗')}</div>`;
 }else if(p&&p.stage==='completed'){
  const a=(s.topic?.attempts||[]).find(x=>x.id===p.last_attempt);body=`<div class="pending-type">${pill('green','Assessment committed')}${a?pill(a.result):''}</div><div class="question">${esc(p.question)}</div><div class="recorded-answer">${esc(p.response||a?.response||'No response text was stored.')}</div>${a?`<div class="button-row">${pill(a.independent?'green':'purple',a.independent?'No substantive help':'Assisted')}${pill('neutral',`Quality ${a.quality}`)}${pill('neutral',a.kind)}</div>${a.capped?`<div class="hint-box">Quality capped: ${esc(a.capped)}</div>`:''}`:''}<p class="subtle m-top">This is the last completed check. Continue the walkthrough or select an eligible concept.</p>`;
 }else{body=`<div class="question-placeholder"><div class="big-icon">?</div><h3>Ready for the first check</h3><p>The plan and answer keys are prepared. Begin the walkthrough to save a question using <code>state.py ask</code>.</p>${source('state','cmd_ask','See the actual ask command ↗')}</div>`;}
 return `<section class="card"><div class="card-head"><div><h2>The current interaction</h2><p>Exactly what the saved question state says</p></div>${pill('neutral',s.pending?.id||'No pending check')}</div><div class="card-body">${body}</div><div class="card-foot">Observed milestone: <b>${esc(label(s.stage))}</b>. ${s.pending?`Key version ${s.pending.rubric_version} · variant ${esc(s.pending.variant)}`:'No model session is embedded in this page.'}</div></section>`;
}
function reviewFocusCard(){const s=state.snapshot,b=currentBeat(),c=s.cards.find(c=>c.node===b.node)||s.cards[0];if(!c)return '';const n=s.topic?.plan?.nodes.find(n=>n.id===c.node);return `<section class="card"><div class="card-head"><div><h2>Review in focus</h2><p>Actual scheduler output · ${esc(c.node)}</p></div>${pill('purple','Review evidence')}</div><div class="card-body"><div class="question">${esc(c.question)}</div><div class="review-stats"><div>INTERVAL<strong>${c.interval}<small>days</small></strong></div><div>EASE<strong>${c.ease}</strong></div><div>REPS<strong>${c.reps}</strong></div><div>LAPSES<strong>${c.lapses}</strong></div></div><p class="subtle">Next due: <b>${esc(c.due)}</b> · demo date ${esc(s.date)}</p><div class="field-label">WHAT THE REVIEWS RECORDED</div><div class="history-chips">${c.history.map(h=>`<div class="history-chip ${h.q>=3?'pass':'fail'}"><span>${esc(h.date)}</span><strong>${h.q}<small>/5</small></strong><span>${esc(h.kind)}</span></div>`).join('')}</div>${n?`<div class="definition-grid">${['coverage','readiness','retention'].map(k=>`<div>${k.toUpperCase()}<br>${pill(n[k])}</div>`).join('')}</div>`:''}<div class="m-top"><button class="primary small" data-view="review">Explore the review lab →</button></div></div><div class="card-foot">${source('scheduler','apply_grade','Inspect the real scheduling rule ↗')}</div></section>`;}
function renderDiff(changes,limit=100){return changes.length?changes.slice(0,limit).map(d=>`<div class="diff-row"><code>${esc(d.path)}</code><span class="before">${esc(pretty(d.before))}</span><span>→</span><span class="after">${esc(pretty(d.after))}</span></div>`).join(''):'<p class="subtle">No state fields changed. This may be a read-only command, such as the recovery hook.</p>';}
function latestEvent(){return state.snapshot.events.at(-1);}
function latestChanges(){const s=state.snapshot,e=latestEvent();const logs=s.topic?.log||[];return `<section class="card"><div class="card-head"><div><h2>${state.mode==='demo'?'What just happened':'Latest saved milestone'}</h2><p>${state.mode==='demo'?'Engine output and committed field changes':'Project log, observed without changing it'}</p></div><button class="text-button" data-view="trace">Full trace ↗</button></div><div class="card-body">${state.mode==='demo'&&e?`<div class="activity-item"><i class="activity-dot"></i><div><code>${esc(e.command.length>150?e.command.slice(0,147)+'…':e.command)}</code><small>${e.duration_ms?`${e.duration_ms} ms · `:''}${e.ok?'Succeeded':'Failed'} · ${esc(e.engine_date||'')}</small></div></div>${renderDiff(e.changes||[],6)}`:logs.length?`<div class="activity-item"><i class="activity-dot"></i><div><strong>${esc(logs.at(-1).event)}</strong><p class="subtle">${esc(logs.at(-1).text)}</p><small>${esc(logs.at(-1).ts)}</small></div></div>`:'<p class="subtle">No saved activity yet. Start a lesson in Claude Code to populate the live view.</p>'}</div></section>`;}
function ownerCard(){return `<section class="card"><div class="card-head"><h2>Who does what?</h2></div><div class="card-body"><div class="owner-item"><span class="owner-icon">✦</span><div><strong>Claude · the teacher</strong><p>Explains, questions and assesses. Replaced by labeled sample inputs in this demo.</p></div></div><div class="owner-item"><span class="owner-icon">⌘</span><div><strong>Python · the rules</strong><p>Applies progression, evidence and scheduling logic.</p></div></div><div class="owner-item"><span class="owner-icon">▤</span><div><strong>Files · the memory</strong><p>Keep prepared lessons, attempts and review dates between sessions.</p></div></div></div><div class="card-foot">${source('system','','Read the project’s system reference ↗')}</div></section>`;}
function classroom(){const s=state.snapshot;selectedNode();return heading('Make the learning process visible.','A local window into the tutor’s decisions, evidence and memory.')+notice()+tour()+phaseStrip()+metrics()+`<div class="main-grid"><div class="stack"><section class="card"><div class="card-head"><div><h2>${esc(s.topic?.title||'No active lesson')}</h2><p>Arrows run from prerequisite to dependent concept</p></div>${pill(s.topic?.status==='finished'?'green':'neutral',s.topic?.status||'Idle')}</div>${graph()}${nodeDetail()}<div class="card-foot"><b>NEXT, from the saved engine state</b><br>${esc(s.topic?.next||'Start a structured lesson in Claude Code to create a plan. The uploaded project has no saved learner state.')}<br>${source('state','eligible','Inspect prerequisite selection ↗')}</div></section>${latestChanges()}</div><div class="stack">${questionCard()}${ownerCard()}</div></div>`;}
function evidence(){const s=state.snapshot,n=s.topic?.plan?.nodes||[],attempts=s.topic?.attempts||[];return heading('Evidence, not a completion checkbox.','Coverage, readiness and retention answer different questions.')+notice()+metrics()+`<section class="card"><div class="card-head"><div><h2>Concept-by-concept evidence</h2><p>Click a row to inspect prepared material and the committed answer key.</p></div>${source('state','cmd_record','Evidence rules ↗')}</div><div class="table-wrap m-top"><table><thead><tr><th>Concept</th><th>Coverage<br><small>Has it been taught?</small></th><th>Readiness<br><small>Can we build on it?</small></th><th>Retention<br><small>Remembered in review?</small></th><th>Evidence / reason</th></tr></thead><tbody>${n.map(x=>`<tr class="clickable-row" data-ui="prep" data-node-id="${esc(x.id)}"><td><strong>${esc(x.label)}</strong><span class="subtle mono">${esc(x.id)}</span></td><td>${pill(x.coverage)}</td><td>${pill(x.readiness)}</td><td>${pill(x.retention)}</td><td><span class="subtle">${esc(x.readiness_note||x.summary||'No recorded assessment yet.')}</span></td></tr>`).join('')||'<tr><td colspan="5">No concepts saved yet.</td></tr>'}</tbody></table></div></section><section class="card section-gap"><div class="card-head"><div><h2>Lesson attempts</h2><p>Sample or presenter-supplied assessments; the Python engine derives their consequences.</p></div>${pill('neutral',`${attempts.length} attempts`)}</div><div class="table-wrap m-top"><table><thead><tr><th>When / concept</th><th>Learner response</th><th>Attempt</th><th>Result</th><th>Help</th><th>Quality</th></tr></thead><tbody>${attempts.slice().reverse().map((a,i)=>`<tr class="clickable-row" data-attempt="${esc(a.id)}"><td>${esc(a.ts.slice(0,10))}<span class="subtle mono">${esc(a.node)} · ${esc(a.variant)}</span></td><td>${esc((a.response||'No response stored').slice(0,130))}${a.response?.length>130?'…':''}</td><td>${pill('neutral',a.kind)}</td><td>${pill(a.result)}</td><td>${pill(a.independent?'green':'purple',a.assistance)}${a.capped?'<span class="subtle">Quality capped</span>':''}</td><td><strong>${a.quality}/5</strong></td></tr>`).join('')||'<tr><td colspan="6">No attempts yet. Run the walkthrough or ask a prepared check.</td></tr>'}</tbody></table></div><div class="card-foot">Reviews recorded with <code>srs.py grade</code> live in each card’s history, not in this lesson-attempt table. See Review lab.</div></section><div class="two-col section-gap"><section class="card"><div class="card-body"><h3>Durable state</h3><p class="subtle m-top">Read the exact current JSON that backs this view. Nothing in the inspector can edit your files.</p><div class="button-row"><button class="secondary" data-json="raw_state">Inspect state.json</button><button class="secondary" data-json="raw_deck">Inspect deck.json</button></div></div></section><section class="card"><div class="card-body"><h3>Memory is not model training</h3><p class="subtle m-top">The tutor adapts using saved evidence and teaching instructions. This project does not implement a model-weight training loop.</p><div class="m-top">${source('teach','','See the teaching method ↗')}</div></div></section></div>`;}
function daysBetween(a,b){return Math.round((Date.parse(b+'T12:00:00Z')-Date.parse(a+'T12:00:00Z'))/86400000);}
function horizon(){const s=state.snapshot;const bins=[{name:'Overdue',value:0},{name:'Today',value:0},{name:'+1 day',value:0},{name:'+2–6',value:0},{name:'+7–14',value:0},{name:'+15–30',value:0},{name:'Later',value:0}];s.cards.filter(c=>!c.suspended).forEach(c=>{let d=daysBetween(s.date,c.due);bins[d<0?0:d===0?1:d===1?2:d<=6?3:d<=14?4:d<=30?5:6].value++;});const max=Math.max(1,...bins.map(b=>b.value));return `<div class="chart"><svg viewBox="0 0 650 150" role="img" aria-label="Current scheduled due dates: ${esc(bins.map(b=>`${b.name}, ${b.value} cards`).join('; '))}"><line x1="20" y1="119" x2="630" y2="119" stroke="#e1e8e2"/>${bins.map((b,i)=>{let h=b.value/max*82,x=34+i*88;return `<rect x="${x}" y="${119-h}" width="48" height="${Math.max(2,h)}" rx="5" fill="${i<2?'#c3a478':'#7eae8c'}"/><text x="${x+24}" y="${110-h}" text-anchor="middle" fill="#526e5c" font-size="12">${b.value}</text><text x="${x+24}" y="139" text-anchor="middle" fill="#85968b" font-size="10">${b.name}</text>`}).join('')}</svg></div><p class="horizon-note">Current due dates only, not a forecast of future performance. Includes all topics in this mode.</p>`;}
function review(){const s=state.snapshot;let selected=s.cards.find(c=>c.id===state.selectedCard)||s.cards[0];state.selectedCard=selected?.id||null;const c=selected;
const header=heading('When should it come back?','Explore the actual review scheduler, one piece of evidence at a time.')+notice();
const controls=state.mode==='demo'?`<div class="notice"><span>↻</span><div><b>Travel through demo time.</b> These buttons change <code>LEARN_NOW</code> for sandbox commands only. Manual changes pause the guided sequence.<div class="button-row"><button class="secondary small" data-advance="1">+1 day</button><button class="secondary small" data-advance="6">+6 days</button><button class="secondary small" data-advance="7">+7 days</button><button class="text-button" data-view="classroom">Back to walkthrough ↗</button></div></div></div>`:'';
if(!c)return header+controls+`<div class="card empty"><h2>No review cards yet</h2><p>The first graded, review-worthy check creates a card through the real engine.</p><button class="primary m-top" data-view="classroom">Go to the walkthrough →</button></div>`;
return header+controls+`<div class="review-layout"><div class="card-list">${s.cards.map(x=>`<button class="review-card ${c.id===x.id?'selected':''}" data-card="${esc(x.id)}"><div>${pill(x.due<=s.date&&!x.suspended?'amber':'green',x.suspended?'Suspended':x.due<=s.date?'Due / overdue':'Scheduled')}</div><h3>${esc((s.topic?.plan?.nodes||[]).find(n=>n.id===x.node)?.label||x.node||x.topic)}</h3><p>Due ${esc(x.due)} · ${x.interval} day interval</p><p class="mono m-top">${esc(x.id)} · ${x.history.length} attempts</p></button>`).join('')}</div><div class="stack"><section class="card"><div class="card-head"><div><h2>Review card · ${esc(c.node)}</h2><p>${esc(c.topic)} · ${esc(c.type)} · ${c.variants?.length||1} prepared variant(s)</p></div>${source('scheduler','apply_grade','Scheduling rules ↗')}</div><div class="card-body"><div class="question">${esc(c.question)}</div><details class="m-top"><summary>Show the committed answer key</summary><p class="subtle">${esc(c.answer)}</p></details><div class="review-stats"><div>INTERVAL<strong>${c.interval}<small>days</small></strong></div><div>EASE<strong>${c.ease}</strong></div><div>REPETITIONS<strong>${c.reps}</strong></div><div>LAPSES<strong>${c.lapses}</strong></div></div><div class="field-label">CARD HISTORY · ACTUAL RECORDED GRADES</div><div class="history-chips">${c.history.map(h=>`<div class="history-chip ${h.q>=3?'pass':'fail'}"><span>${esc(h.date)}</span><strong>${h.q}<small>/5</small></strong><span>${esc(h.kind)}</span>${h.early?'<span>Early review</span>':''}${h.valid===false?'<span>Invalidated key</span>':''}</div>`).join('')||'<p class="subtle">No graded attempts.</p>'}</div>${s.can_write?`<div class="border-top"><div class="field-label">SUPPLY A REVIEW ASSESSMENT</div><p class="subtle">This is a scheduling experiment, not automatic grading. Pick the evidence you want the engine to receive.</p><div class="button-row"><select class="inline-select" id="review-kind" aria-label="Review attempt kind"><option value="review">Scheduled review</option><option value="practice">Immediate practice</option><option value="repair">Repair</option></select><label class="subtle"><input type="checkbox" id="review-assisted"> Assisted</label></div><div class="button-row"><button class="primary small" data-review-grade="4">Pass · request quality 4</button><button class="secondary small" data-review-grade="1">Failed recall · 1</button><button class="text-button" data-json-card="${esc(c.id)}">Inspect card JSON ↗</button></div></div>`:''}<div class="rule-callout">Practice / repair success does not extend the interval. Same-day extra successes do not advance it twice. A failure still schedules the card for tomorrow.</div></div></section><section class="card"><div class="card-head"><div><h2>The current review horizon</h2><p>${s.due.selected.length} card(s) selected by the engine’s review budget · ${s.due.deferred.length} deferred</p></div></div><div class="card-body">${horizon()}</div></section></div></div>`;}
const methods=[
 ['01','Start from the learner','The teaching skill reads the learner profile and uses probing questions to establish a starting point. Adaptation is implemented through instructions and saved evidence, not a trained curriculum-selection model.','teach',''],
 ['02','Prepare before assessing','Objectives, misconceptions, questions and committed answer keys are stored before the learner answers. A document-reader digest can scope a lesson; no vector database is required by this implementation.','state','cmd_prep_node'],
 ['03','Gate only the relevant prerequisites','eligible() selects uncovered nodes whose prerequisites are covered and not needs_repair. A weak branch does not block unrelated concepts. Provisional and unknown prerequisites have different caveats but do not block this function.','state','eligible'],
 ['04','Distinguish help from independent recall','The engine records the hint ladder and caps scheduling quality for substantive assistance. A supported pass can become provisional rather than independently ready. The demo makes that distinction visible.','state','cmd_record'],
 ['05','Revisit using dated evidence','Review cards are selected by due date and a time budget. apply_grade() distinguishes initial learning, practice, repair and review, including same-day and early-review safeguards.','scheduler','apply_grade'],
 ['06','Recover the lesson, not the chat','A session-start hook injects a compact summary of saved progress, a pending question and the next action. The state store commits state and deck with a lock, schema validation and recoverable journal.','store','commit'],
 ['07','Apply ideas through coding','exercise.py creates Python, JavaScript and C/OpenMP tasks and runs validation/check commands. This dashboard does not include a coding editor or execute arbitrary learner code.','exercise',''],
 ['08','Know the implementation’s limits','Claude still supplies the semantic assessment. The scripts trust that structured input. In the supplied version an unassisted repair pass can become ready; the teaching instructions describe a more conservative policy.','state','cmd_record']
];
function architecture(){return heading('A teacher, a rule engine, and memory.','The actual project architecture—without an invented RAG pipeline.')+notice()+`<div class="architecture-grid"><section class="arch-card purple"><span class="pill purple">TEACHING BEHAVIOR</span><h2>Claude Code</h2><p>Turns prepared material into an adaptive conversation with the learner.</p><div class="arch-row"><b>Teaching & review skills</b><p>Markdown instructions define how to teach, question, repair and review.</p></div><div class="arch-row"><b>Profile & specialist agents</b><p>Learner preferences; research, document digests and optional diagrams.</p></div><div class="arch-row"><b>Semantic assessment</b><p>Claude judges meaning against the prepared key. Python receives that assessment.</p></div><div class="arch-foot">Demo boundary: prepared sample inputs replace this layer.</div></section><div class="arch-arrow">→</div><section class="arch-card green"><span class="pill green">EXECUTABLE RULES</span><h2>Python commands</h2><p>Make saved progress and scheduling consistent across interactions.</p><div class="arch-row"><b>state.py</b><p>Plan, ask, answer, hint, record, prerequisites and completion conditions.</p></div><div class="arch-row"><b>srs.py</b><p>Due selection, grading, evidence safeguards and SM-2 intervals.</p></div><div class="arch-row"><b>exercise.py & learnlib.py</b><p>Exercise checks; configuration, validation, locking and durable storage.</p></div><div class="arch-foot">This layer actually runs in the interactive demo.</div></section><div class="arch-arrow">⇄</div><section class="arch-card amber"><span class="pill amber">DURABLE MEMORY</span><h2>Local files</h2><p>The lesson survives even when the conversation context does not.</p><div class="arch-row"><b>state.json</b><p>Concept states, pending question, attempts, topic preparation and NEXT.</p></div><div class="arch-row"><b>deck.json & prep/</b><p>Review dates, history, question variants and committed answer keys.</p></div><div class="arch-row"><b>Notes & session hooks</b><p>Readable lesson history and context recovery at session start.</p></div><div class="arch-foot">SessionStart reads memory back into the teacher’s context.</div></section></div><div class="notice section-gap"><span>↺</span><div><b>The feedback loop:</b> teach → ask → assess → record evidence → choose what to teach or review next. Improvement means a better-supported learner model and learning decisions, not model-weight training.</div></div><div class="method-grid">${methods.map(([n,title,text,file,fn])=>`<section class="method"><div class="eyebrow">MECHANISM ${n}</div><h3>${title}</h3><p>${text}</p>${source(file,fn)}</section>`).join('')}</div><section class="card section-gap"><div class="card-body"><h3>What this observatory can actually observe</h3><p class="subtle m-top">The phase ribbon is a labeled interpretation of persistent state, and guided-demo phases are presentation annotations. The trace shows executed dashboard commands or saved project log events. It does not claim to track unsaved explanations, live subagent activity, token generation or hidden model reasoning.</p><div class="button-row"><button class="secondary" data-view="trace">Inspect the execution trace →</button>${source('system','','Read docs/SYSTEM.md ↗')}</div></div></section>`;}
function eventsForTrace(){const s=state.snapshot;const own=s.events.map(e=>({...e,origin:'command'}));const observed=(s.topic?.log||[]).map((e,i)=>({id:`log-${i}-${e.ts}`,at:e.ts,command:`Saved milestone: ${e.event}`,output:e.text,changes:[],input:null,ok:true,origin:'observation',engine_date:e.ts?.slice(0,10)}));return state.mode==='live'?[...observed,...own].sort((a,b)=>a.at.localeCompare(b.at)):own;}
function trace(){const s=state.snapshot,events=eventsForTrace();let e=events.find(x=>x.id===state.selectedEvent)||events.at(-1);state.selectedEvent=e?.id||null;let detail='';if(e){detail=state.traceTab==='output'?`<pre class="terminal">${esc(e.output||'(No stdout.)')}</pre>`:state.traceTab==='input'?`<p class="subtle">${e.origin==='observation'?'This event was observed in the project log. Its original command input is not captured by the dashboard.':'Exact JSON or text supplied by this dashboard to the command. The assessment is an input, not an AI-generated output.'}</p><pre class="json-code">${esc(e.input===null||e.input===undefined?'No stdin payload.':typeof e.input==='string'?e.input:JSON.stringify(e.input,null,2))}</pre>`:renderDiff(e.changes||[]);}
return heading('Show the work the software actually did.','Inspect commands, structured inputs, engine output and committed state changes.')+notice()+`<div class="trace-layout"><section class="card"><div class="card-head"><div><h2>${state.mode==='live'?'Saved activity & browser commands':'Dashboard command history'}</h2><p>Newest first · ${events.length} visible events</p></div></div><div class="event-list m-top">${events.slice().reverse().map(x=>`<button class="event-button ${x.id===state.selectedEvent?'selected':''}" data-event="${esc(x.id)}"><span class="event-meta">${pill(x.ok?'green':'red',x.origin==='observation'?'Observed':x.ok?'Executed':'Failed')}<span>${esc(x.engine_date||x.at.slice(0,10))}</span>${x.duration_ms?`<span>${x.duration_ms} ms</span>`:''}</span><code>${esc(x.command.length>140?x.command.slice(0,137)+'…':x.command)}</code></button>`).join('')||'<div class="empty">No saved events yet.</div>'}</div></section><div class="stack"><section class="card"><div class="card-head"><div><h2>${e?'Event details':'No event selected'}</h2><p>${e?esc(e.at):'Run a demonstration step to populate the trace.'}</p></div>${e?pill(e.ok?'green':'red',e.ok?'Succeeded / observed':'Failed'):''}</div><div class="card-body">${e?`<div class="trace-tabs"><button class="${state.traceTab==='output'?'selected':''}" data-trace-tab="output">Output</button><button class="${state.traceTab==='input'?'selected':''}" data-trace-tab="input">Input payload</button><button class="${state.traceTab==='changes'?'selected':''}" data-trace-tab="changes">State changes</button></div><code class="subtle">${esc(e.command)}</code>${detail}`:''}</div></section><section class="card"><div class="card-body"><h3>Recoverable context</h3><p class="subtle m-top">The current summary comes from <code>state.summary_text()</code>. The isolated-demo button executes the actual SessionStart hook in a fresh process.</p><pre class="json-code">${esc(s.summary)}</pre><div class="button-row"><button class="secondary small" data-action="recover" ${state.mode!=='demo'?'disabled':''}>Run recovery hook in demo</button>${source('hook','main','Inspect hook ↗')}</div></div></section><section class="card"><div class="card-body"><h3>Inspect or export a snapshot</h3><div class="button-row"><button class="secondary small" data-json="raw_state">state.json</button><button class="secondary small" data-json="raw_deck">deck.json</button><button class="text-button" data-ui="export">Export current snapshot ↗</button></div><p class="subtle m-top">Exports include answers, keys and local file paths. Treat a live-project export as personal learning data.</p></div></section></div></div>`;}
function render(){const s=state.snapshot;if(!s)return;$('#page-name').textContent=names[state.view];$$('[data-view]').forEach(b=>b.classList.toggle('active',b.dataset.view===state.view));$('#mode-demo').classList.toggle('selected',state.mode==='demo');$('#mode-live').classList.toggle('selected',state.mode==='live');$('#mode-demo').setAttribute('aria-pressed',state.mode==='demo');$('#mode-live').setAttribute('aria-pressed',state.mode==='live');$('#content').innerHTML=({classroom,evidence,review,architecture,trace}[state.view])();$('#footer-source').textContent=`${state.mode==='demo'?'SANDBOX':'PROJECT'} · state rev ${s.rev} / deck rev ${s.deck_rev} · ${s.state_path}`;$('#presentation-nav').innerHTML=Object.entries(names).map(([v,n])=>`<button data-view="${v}" class="${state.view===v?'active':''}">${n}</button>`).join('');}
async function showSource(file,fn=''){try{const d=await api(`/api/source?mode=${state.mode}&file=${encodeURIComponent(file)}`);const lines=d.text.split('\n');let target=fn?lines.findIndex(x=>x.startsWith(`def ${fn}(`)||x.trimStart().startsWith(`def ${fn}(`)):0;if(target<0)target=0;let end=target+1;while(end<lines.length&&end<target+95&&(!/^def |^class /.test(lines[end])||end===target+1))end++;modal(d.path,`<div class="source-meta">Read from ${state.mode==='demo'&&d.path.startsWith('scripts/')?'the isolated copy of your actual scripts':'your project'}. SHA-256: <span class="mono">${esc(d.sha256)}</span></div><pre class="source-pre">${lines.map((line,i)=>`<span class="source-line ${fn&&i>=target&&i<end?'highlight':''}" id="source-L${i+1}"><span class="ln">${i+1}</span>${esc(line)}</span>`).join('')}</pre>`,'ACTUAL SOURCE CODE · READ-ONLY');setTimeout(()=>{const el=$(`#source-L${target+1}`);if(el)el.parentElement.scrollTop=Math.max(0,el.offsetTop-el.parentElement.offsetTop-30);},30);}catch(e){toast(e.message,true);}}
function showPrep(id){const s=state.snapshot,n=(s.topic?.plan?.nodes||[]).find(n=>n.id===id),p=s.prep[id];if(!p)return modal(n?.label||id,'<p>No prepared material was saved for this node.</p>');modal(`${n?.label||id} · prepared material`,`<div class="modal-prose"><div class="notice"><span>▤</span><div>Stored before the learner answers. These are prepared teaching inputs, not content generated by this dashboard.</div></div><h3>Objective</h3><p>${esc(p.objective)}</p><h3>Motivation</h3><p>${esc(p.motivation||p.why_needed||'Not specified')}</p><h3>Explanation outline</h3><ol class="steps">${(p.outline||[]).map(x=>`<li>${esc(typeof x==='string'?x:JSON.stringify(x))}</li>`).join('')}</ol><h3>Misconceptions and targeted repair</h3>${(p.misconceptions||[]).map(m=>`<div class="hint-box"><b>${esc(m.text)}</b><br>${esc(m.repair)}</div>`).join('')||'<p>None saved.</p>'}<h3>Committed checks and keys</h3>${(p.checks||[]).map(c=>`<section class="card m-top"><div class="card-body"><div class="pending-type">${pill('purple',c.type)}${pill('neutral',c.id)}${pill('green',c.review?'Review-worthy':'Not promoted')}</div>${c.variants.map(v=>`<details class="m-top"><summary>${esc(v.id)} · ${esc(v.question)}</summary><p>${esc(v.answer)}</p><div class="field-label">REQUIRED POINTS</div><ul>${(v.required||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ul></details>`).join('')}<h3>Hint ladder</h3><ol class="steps">${(c.hints||[]).map(x=>`<li>${esc(x)}</li>`).join('')}</ol></div></section>`).join('')}<div class="m-top">${source('state','cmd_prep_node','How preparation is saved ↗')}</div></div>`,'COMMITTED LESSON PREPARATION');}
function showHelp(){modal('Run it locally. Present the real system.',`<div class="modal-prose"><h3>Start the server</h3><p>From the extracted project folder, run:</p><pre class="json-code">python3 dashboard/server.py</pre><p>On Windows use <code>py dashboard/server.py</code>, or double-click <code>Start dashboard.bat</code>. The browser opens the localhost address printed by the server. Python 3.10+ is required. No pip, Node, model key or internet connection is needed for the demo.</p><h3>Present the prepared story</h3><p>Choose <b>Isolated demo</b>, then <b>Begin walkthrough</b>. Each Next step runs real project commands with labeled sample answers and assessments. Show the blocked branch, hint cap, recovery output and review intervals. The fraction lesson is a presentation fixture, not a saved learner’s history.</p><p><b>Keyboard:</b> F toggles presentation layout. Right arrow advances the guided walkthrough when focus is not in an input. Escape closes a dialog or exits presentation layout. Speaker notes provide a sentence for each step.</p><h3>Observe an existing checkout</h3><pre class="json-code">python3 dashboard/server.py --project "/path/to/your/LearningforLunch"</pre><p>Switch to <b>Live project</b> and continue the lesson in Claude Code in that same checkout. The dashboard polls saved milestones every 1.5 seconds. If that checkout has no learner state, the empty live view is expected.</p><h3>Optional live interaction</h3><pre class="json-code">python3 dashboard/server.py --project "/path/to/your/LearningforLunch" --enable-live-controls</pre><p>This explicitly enables browser ask, answer, hint, assessment and review writes to real records. Each action asks for confirmation. Stale state revisions are rejected inside the engine write lock. Coordinate with Claude rather than grading the same interaction in two places.</p><h3>What is—and is not—live</h3><p>The underlying scripts and saved state are real. The phase label summarizes observed state; the guided-demo phase is a presentation annotation. There is no embedded Claude chat, autonomous grading, background researcher tracking or hidden-reasoning view.</p><h3>Safety & troubleshooting</h3><p>The server binds only to <code>127.0.0.1</code>. Demo files are under <code>.dashboard-local/demo/</code>; Reset deletes only that marked sandbox. Keep the terminal open. Use <code>--port 8766</code> if the default port is occupied. Stop with Ctrl+C. Read <code>dashboard/README.md</code> for more details.</p></div>`,'PRESENTATION & LOCAL SETUP');}
function togglePresentation(){document.body.classList.toggle('presenting');$('#present').setAttribute('aria-pressed',document.body.classList.contains('presenting'));}

// Delegated events keep controls functional after live state rerenders.
document.addEventListener('click',async event=>{
 const el=event.target.closest('button,[data-node],[data-attempt],tr[data-ui]');if(!el||el.disabled)return;
 if(el.dataset.source){await showSource(el.dataset.source,el.dataset.function);return;}
 if(el.dataset.view){changeView(el.dataset.view);return;}
 if(el.dataset.phase){const p=phases.find(p=>p.id===el.dataset.phase);modal(p.title,`<p>${esc(p.text)}</p><div class="notice"><span>⌘</span><div><b>${esc(p.owner)}</b></div></div>${source(p.file,p.fn)}`,'LEARNING CYCLE · EXPLANATION');return;}
 if(el.dataset.node){state.selectedNode=el.dataset.node;render();return;}
 if(el.dataset.card){state.selectedCard=el.dataset.card;render();return;}
 if(el.dataset.event){state.selectedEvent=el.dataset.event;render();return;}
 if(el.dataset.traceTab){state.traceTab=el.dataset.traceTab;render();return;}
 if(el.dataset.json){modal(el.dataset.json==='raw_state'?'state.json · current snapshot':'deck.json · current snapshot',`<pre class="json-code">${esc(JSON.stringify(state.snapshot[el.dataset.json],null,2))}</pre>`,'LIVE DATA · READ-ONLY INSPECTOR');return;}
 if(el.dataset.jsonCard){const c=state.snapshot.cards.find(c=>c.id===el.dataset.jsonCard);modal('Review card · raw data',`<pre class="json-code">${esc(JSON.stringify(c,null,2))}</pre>`);return;}
 if(el.dataset.attempt){const a=state.snapshot.topic.attempts.find(a=>a.id===el.dataset.attempt);modal(`Attempt ${a.id}`,`<pre class="json-code">${esc(JSON.stringify(a,null,2))}</pre>`,'RECORDED LESSON EVIDENCE');return;}
 if(el.dataset.action){await act(el.dataset.action);return;}
 if(el.dataset.advance){await act('advance-clock',{days:Number(el.dataset.advance)});return;}
 if(el.dataset.reviewGrade){await act('grade-review',{card:state.selectedCard,quality:Number(el.dataset.reviewGrade),kind:$('#review-kind').value,assisted:$('#review-assisted').checked});return;}
 if(el.dataset.ui){
   switch(el.dataset.ui){
    case 'notes':state.showNotes=!state.showNotes;render();break;
    case 'prep':showPrep(el.dataset.nodeId);break;
    case 'ask-node':{const n=state.snapshot.topic.plan.nodes.find(n=>n.id===el.dataset.nodeId);await act('ask',{node:n.id,kind:n.readiness==='needs_repair'?'repair':n.coverage==='covered'?'practice':'initial'});break;}
    case 'save-answer':await act('answer',{response:$('#learner-answer').value});break;
    case 'grade':await act('record',{result:el.dataset.result,quality:el.dataset.result==='fail'?1:Number($('#grade-quality').value),required_met:[...state.met]});break;
    case 'export':{const a=document.createElement('a');a.href=`/api/export?mode=${state.mode}`;a.download=`learning-observatory-${state.mode}.json`;a.click();break;}
   }
 }
});
document.addEventListener('input',event=>{if(event.target.id==='learner-answer')state.draft=event.target.value;});
document.addEventListener('change',event=>{if(event.target.dataset.required!==undefined){const r=state.snapshot.pending.key.required[Number(event.target.dataset.required)];event.target.checked?state.met.add(r):state.met.delete(r);}});
document.addEventListener('keydown',event=>{
 if(event.target.matches('input,textarea,select,[contenteditable=true]'))return;
 if(event.key==='Enter'&&event.target.matches('[data-node]')){event.preventDefault();state.selectedNode=event.target.dataset.node;render();return;}
 if($('#modal').open)return;
 if(event.key.toLowerCase()==='f'){event.preventDefault();togglePresentation();}
 if(event.key==='Escape'&&document.body.classList.contains('presenting'))togglePresentation();
 if(event.key==='ArrowRight'&&state.mode==='demo'&&state.view==='classroom'&&!state.snapshot?.tour?.tour_custom){event.preventDefault();if(state.snapshot.tour.tour_index<state.snapshot.tour.steps.length)act('tour-next');}
});
$('#mode-demo').addEventListener('click',()=>switchMode('demo'));
$('#mode-live').addEventListener('click',()=>switchMode('live'));
async function switchMode(mode){if(state.busy||state.mode===mode)return;state.mode=mode;state.selectedNode=null;state.selectedCard=null;state.selectedEvent=null;state.draft='';state.met=new Set();state.signature='';// let any old poll finish; never apply a response from the other mode
 while(state.polling)await new Promise(r=>setTimeout(r,30));await load(true);}
$('#refresh').addEventListener('click',()=>load(true));$('#present').addEventListener('click',togglePresentation);$('#help').addEventListener('click',showHelp);$('#modal-close').addEventListener('click',()=>$('#modal').close());
$('#modal').addEventListener('click',event=>{if(event.target===$('#modal')){const r=event.target.getBoundingClientRect();if(event.clientX<r.left||event.clientX>r.right||event.clientY<r.top||event.clientY>r.bottom)event.target.close();}});
(async()=>{try{const b=await api('/api/bootstrap');state.token=b.token;await load(true);setInterval(()=>{if(!document.hidden)load();},1500);}catch(error){setConnection(false);$('#content').innerHTML=`<div class="card empty"><h2>Start the local Python server first</h2><p>${esc(error.message)}</p><pre class="json-code">python3 dashboard/server.py</pre><p>Use its localhost address, not a file:// URL.</p></div>`;}})();
